parameters.jsCode:
const response = $input.first().json;

// Extract the image URL from OpenRouter response
let imageUrl = '';

if (response.choices && response.choices[0]) {
  const content = response.choices[0].message.content;

  // OpenRouter returns image URL in the content
  if (typeof content === 'string' && content.includes('http')) {
    // Extract URL from content
    const urlMatch = content.match(/(https?:\/\/[^\s]+)/g);
    if (urlMatch) {
      imageUrl = urlMatch[0];
    }
  } else if (content.image_url) {
    imageUrl = content.image_url;
  }
}

const inputData = $input.first().json;

return [{ 
  json: { 
    imageUrl: imageUrl,
    topic: inputData.topic || 'unknown',
    brandName: inputData.brandName || 'logo',
    clientName: inputData.clientName || 'Client',
    clientEmail: inputData.clientEmail || '',
    variationNumber: inputData.variationNumber || 1
  } 
}];

// Aggregate all logo links for the email
const items = $input.all();
const links = items.map(item => {
  const fileId = item.json.id;
  const fileName = item.json.name;
  const variationNumber = item.json.variationNumber;
  return `Variation ${variationNumber}: https://drive.google.com/file/d/${fileId}/view`;
}).join('\n');

const firstItem = items[0].json;

return [{
  json: {
    clientName: firstItem.clientName,
    clientEmail: firstItem.clientEmail,
    brandName: firstItem.brandName,
    topic: firstItem.topic,
    variations: items.length,
    logoLinks: links
  }
}];

const variations = $input.first().json.variations;
const topic = $input.first().json.topic;
const brandName = $input.first().json.brandName;
const clientName = $input.first().json.clientName;
const clientEmail = $input.first().json.clientEmail;

const items = [];
for (let i = 1; i <= variations; i++) {
  items.push({
    json: {
      topic: topic,
      brandName: brandName,
      clientName: clientName,
      clientEmail: clientEmail,
      variationNumber: i
    }
  });
}

return items;
